def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    def strip_ns(tag: str) -> str:
        return tag.split("}", 1)[-1] if "}" in tag else tag

    def update_status(key: str, status: str) -> None:
        if key in results:
            current = results[key]
            if current == "fail":
                return
            if status == "fail":
                results[key] = "fail"
                return
            if current == "skip":
                return
        results[key] = status

    def handle_root(root: ET.Element) -> None:
        for case in root.iter():
            if strip_ns(case.tag) != "testcase":
                continue
            classname = case.get("classname") or case.get("class") or ""
            name = case.get("name") or case.get("id") or "unknown"
            test_name = f"{classname}::{name}" if classname else name
            status = "pass"
            for child in list(case):
                tag = strip_ns(child.tag)
                if tag == "skipped":
                    status = "skip"
                elif tag in ("failure", "error"):
                    status = "fail"
            update_status(test_name, status)

    snippets: list[str] = []

    # Extract testsuite blocks
    snippets.extend(re.findall(r"<testsuite\b[^>]*>.*?</testsuite>", log, re.DOTALL))
    snippets.extend(re.findall(r"<testsuite\b[^>]*/>", log))
    if not snippets:
        snippets.extend(re.findall(r"<testsuites\b[^>]*>.*?</testsuites>", log, re.DOTALL))
    if not snippets and "<testcase" in log:
        snippets.append(log)

    for snippet in snippets:
        cleaned = re.sub(r"<\?xml[^>]*\?>", "", snippet).strip()
        if not cleaned:
            continue
        try:
            root = ET.fromstring(cleaned)
            handle_root(root)
            continue
        except ET.ParseError:
            # Try wrapping multiple top-level suites
            try:
                wrapped = f"<root>{cleaned}</root>"
                root = ET.fromstring(wrapped)
                handle_root(root)
            except ET.ParseError:
                continue

    # Fallbacks for common text outputs
    pytest_pattern = re.compile(r"^(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|ERROR)\b", re.MULTILINE)
    for name, status in pytest_pattern.findall(log):
        update_status(name, "fail" if status in ("FAILED", "ERROR") else "skip" if status == "SKIPPED" else "pass")

    unittest_pattern = re.compile(r"^(\w+(?:\.\w+)+)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)", re.MULTILINE)
    for name, status in unittest_pattern.findall(log):
        update_status(name, "fail" if status in ("FAIL", "ERROR") else "skip" if status == "skipped" else "pass")

    go_pattern = re.compile(r"^---\s+(PASS|FAIL|SKIP):\s+(\S+)", re.MULTILINE)
    for status, name in go_pattern.findall(log):
        update_status(name, "fail" if status == "FAIL" else "skip" if status == "SKIP" else "pass")

    jest_pattern = re.compile(r"^(PASS|FAIL)\s+(\S+)", re.MULTILINE)
    for status, name in jest_pattern.findall(log):
        update_status(name, "fail" if status == "FAIL" else "pass")

    jest_symbol_pattern = re.compile(r"^[\s│]*([✓✕○])\s+(.+)$", re.MULTILINE)
    for symbol, name in jest_symbol_pattern.findall(log):
        symbol = symbol.strip()
        status = "pass" if symbol == "✓" else "skip" if symbol == "○" else "fail"
        update_status(name.strip(), status)

    return results
